// set_membership: proves a private attribute is a leaf in a Poseidon2 Merkle
// tree whose root is public. The circuit also binds the attribute to a
// credential commitment signed by a trusted issuer, so the proof is both a
// membership proof and a credential proof.
//
// Public input layout (each field is 32 bytes big-endian, in order):
//   [0]   commitment  -- Poseidon2([value, salt], 2); value=840, salt=42
//   [1]   issuer_x    -- secp256k1 pub key X (demo issuer, from sign.js)
//   [2]   issuer_y    -- secp256k1 pub key Y
//   [3]   merkle_root -- Poseidon2 root of {840,276,566,356} padded to 256 leaves
//
// Witness: value=840 (US, ISO 3166-1), leaf index 0 in the sample allowlist.
// Salt is non-zero (42) per the Poseidon2 commitment discipline in #296.
//
// Fixtures generated by:
//   node circuits/scripts/gen_inputs.sh      # writes set_membership/Prover.toml
//   bash circuits/scripts/build.sh set_membership
// and committed to fixtures/set_membership/{vk,proof,public_inputs}.
// To regenerate: re-run those two commands with nargo 1.0.0-beta.9 + bb 0.87.0.
#[test]
fn verifies_set_membership() {
    let env = Env::default();
    env.mock_all_auths();
    let c = setup(&env);
    c.set_vk(
        &Symbol::new(&env, "set_membership"),
        &1u32,
        &Bytes::from_slice(&env, fixture!("set_membership", "vk")),
    );
    assert!(c.verify_proof(
        &Symbol::new(&env, "set_membership"),
        &Bytes::from_slice(&env, fixture!("set_membership", "proof")),
        &Bytes::from_slice(&env, fixture!("set_membership", "public_inputs")),
        &None,
    ));
}

// A single flipped bit anywhere in the set_membership proof must cause
// verification to fail, confirming the on-chain verifier actually checks
// the proof bytes rather than trivially returning true.
#[test]
fn rejects_tampered_set_membership_proof() {
    let env = Env::default();
    env.mock_all_auths();
    let c = setup(&env);
    c.set_vk(
        &Symbol::new(&env, "set_membership"),
        &1u32,
        &Bytes::from_slice(&env, fixture!("set_membership", "vk")),
    );
    let mut bad = fixture!("set_membership", "proof").to_vec();
    bad[5000] ^= 0xff;
    assert!(!c.verify_proof(
        &Symbol::new(&env, "set_membership"),
        &Bytes::from_slice(&env, &bad),
        &Bytes::from_slice(&env, fixture!("set_membership", "public_inputs")),
        &None,
    ));
}

